input.content:
:root {
  --bg-1: #091015;
  --bg-2: #0f171d;
  --panel: rgba(11, 18, 22, 0.9);
  --panel-border: rgba(130, 160, 180, 0.3);
  --text: #e6edf3;
  --muted: #9bb0bd;
  --accent: #8ad66c;
  --accent-2: #ffb648;
  --danger: #ff5d5d;
  --shadow: rgba(0, 0, 0, 0.35);
  --tile: #21313d;
  --tile-dark: #14242d;
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  min-height: 100%;
  font-family: Inter, "Segoe UI", sans-serif;
  background: radial-gradient(circle at top, #12222a, var(--bg-1) 42%, #05090d 100%);
  color: var(--text);
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 18px;
}

button {
  cursor: pointer;
  border: 1px solid rgba(255,255,255,0.08);
  background: linear-gradient(180deg, #1d2b33, #131d24);
  color: var(--text);
  border-radius: 10px;
  padding: 10px 12px;
  font-weight: 700;
  letter-spacing: 0.02em;
  transition: transform 0.15s ease, border-color 0.15s ease;
}

button:hover {
  transform: translateY(-1px);
  border-color: rgba(138, 214, 108, 0.9);
}

#game-shell {
  width: min(1280px, 100%);
  min-height: min(92vh, 820px);
  background: rgba(7, 12, 16, 0.86);
  border: 1px solid var(--panel-border);
  border-radius: 18px;
  box-shadow: 0 30px 60px var(--shadow);
  overflow: hidden;
}

.topbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px 22px;
  background: rgba(17, 27, 34, 0.9);
  border-bottom: 1px solid var(--panel-border);
}

.brand {
  font-size: clamp(1rem, 2vw, 1.5rem);
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--accent);
  font-weight: 800;
}

.stats {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.stats div {
  min-width: 84px;
  padding: 8px 10px;
  border-radius: 10px;
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.08);
  display: flex;
  flex-direction: column;
  line-height: 1.1;
}

.stats span {
  font-size: 0.68rem;
  text-transform: uppercase;
  color: var(--muted);
}

.stats strong {
  font-size: 1.2rem;
}

.play-area {
  display: grid;
  grid-template-columns: 260px minmax(0, 1fr) 260px;
  min-height: 760px;
}

.panel {
  background: rgba(9, 14, 20, 0.82);
  border-right: 1px solid var(--panel-border);
  padding: 18px 16px;
}

.right-panel {
  border-right: none;
  border-left: 1px solid var(--panel-border);
}

.panel h3 {
  margin: 0 0 10px;
  color: var(--accent-2);
  font-size: 0.95rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

#objectiveList {
  margin: 0 0 22px;
  padding-left: 18px;
  color: var(--text);
  line-height: 1.75;
}

.inventory {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  min-height: 120px;
}

.slot {
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
  color: var(--muted);
  font-size: 0.85rem;
  font-weight: 700;
}

.slot.filled {
  color: var(--text);
  background: rgba(138, 214, 108, 0.08);
  border-color: rgba(138, 214, 108, 0.3);
}

.arena-wrap {
  display: flex;
  align-items: stretch;
  justify-content: center;
  padding: 18px;
}

.arena {
  position: relative;
  width: min(100%, 760px);
  aspect-ratio: 1.25;
  border-radius: 18px;
  overflow: hidden;
  border: 2px solid rgba(130, 160, 180, 0.35);
  background:
    linear-gradient(180deg, rgba(16, 38, 47, 0.95), rgba(8, 13, 18, 0.96)),
    linear-gradient(90deg, rgba(34, 48, 52, 0.4) 1px, transparent 1px),
    linear-gradient(rgba(34, 48, 52, 0.4) 1px, transparent 1px);
  background-size: auto, 36px 36px, 36px 36px;
  box-shadow: inset 0 0 24px rgba(0,0,0,0.28);
}

.arena::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 50% 15%, rgba(151, 211, 255, 0.08), transparent 42%);
  pointer-events: none;
}

.player,
.enemy,
.resource,
.campfire,
.shelter {
  position: absolute;
  transform: translate(-50%, -50%);
  transition: left 0.35s ease, top 0.35s ease, transform 0.2s ease;
}

.player {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background: linear-gradient(180deg, #d8f1ff, #6cc1ff);
  border: 2px solid rgba(255,255,255,0.9);
  box-shadow: 0 0 15px rgba(108, 193, 255, 0.9);
  z-index: 10;
}

.player::after {
  content: "";
  position: absolute;
  width: 6px;
  height: 20px;
  background: #eaeef5;
  border-radius: 6px;
  left: 50%;
  bottom: -16px;
  transform: translateX(-50%);
}

.enemy {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: linear-gradient(180deg, #d2f4a8, #4f8d32);
  border: 2px solid rgba(14, 28, 12, 0.8);
  box-shadow: inset 0 0 12px rgba(0,0,0,0.2);
}

.zombie {
  animation: pulse 1.7s infinite ease-in-out;
}

@keyframes pulse {
  0%, 100% { transform: translate(-50%, -50%) scale(1); }
  50% { transform: translate(-50%, -50%) scale(1.08); }
}

.resource {
  width: 36px;
  height: 36px;
  border-radius: 12px;
  opacity: 0.95;
}

.tree {
  background: linear-gradient(180deg, #6bbd6d, #356a32);
  clip-path: polygon(50% 0%, 62% 22%, 100% 20%, 78% 42%, 100% 75%, 50% 100%, 0% 75%, 22% 42%, 0% 20%, 38% 22%);
}

.rock {
  background: linear-gradient(180deg, #b8b4b4, #6a6b78);
  border-radius: 50% 42% 48% 52%;
}

.water {
  background: linear-gradient(180deg, #8ad6ff, #355dff);
  border-radius: 50%;
  box-shadow: inset 0 0 12px rgba(255,255,255,0.45);
}

.campfire {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: radial-gradient(circle, #ffd49e, #ff8d3f 44%, #d64d25 72%);
  box-shadow: 0 0 20px rgba(255, 164, 77, 0.8);
}

.shelter {
  width: 74px;
  height: 42px;
  border-radius: 10px 10px 18px 18px;
  background: linear-gradient(180deg, #d6d7d9, #7b7e84);
  border: 2px solid rgba(255,255,255,0.25);
}

.message-box {
  position: absolute;
  left: 50%;
  top: 20px;
  transform: translateX(-50%);
  max-width: 74%;
  background: rgba(8, 18, 22, 0.8);
  border: 1px solid rgba(255,255,255,0.12);
  border-radius: 12px;
  padding: 10px 14px;
  font-size: 0.82rem;
  text-align: center;
  color: var(--text);
  z-index: 20;
  box-shadow: 0 10px 26px rgba(0,0,0,0.22);
}

.controls {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  margin-bottom: 18px;
}

.event-log {
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: 280px;
  overflow-y: auto;
  color: var(--muted);
  font-size: 0.82rem;
  line-height: 1.5;
}

.event-log div {
  padding: 8px 10px;
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 8px;
}

@media (max-width: 980px) {
  .play-area {
    grid-template-columns: 1fr;
  }

  .panel {
    border: none;
    border-bottom: 1px solid var(--panel-border);
  }

  .right-panel {
    border-left: none;
    border-top: 1px solid var(--panel-border);
  }

  .topbar {
    flex-direction: column;
    gap: 14px;
    align-items: flex-start;
  }
}

const arena = document.getElementById('arena');
const playerEl = document.getElementById('player');
const messageBox = document.getElementById('messageBox');
const inventoryEl = document.getElementById('inventory');
const eventLogEl = document.getElementById('eventLog');
const objectiveList = document.getElementById('objectiveList');

const dayValue = document.getElementById('dayValue');
const foodValue = document.getElementById('foodValue');
const waterValue = document.getElementById('waterValue');
const healthValue = document.getElementById('healthValue');
const energyValue = document.getElementById('energyValue');

const state = {
  day: 1,
  food: 30,
  water: 28,
  health: 100,
  energy: 100,
  wood: 0,
  stone: 0,
  meds: 0,
  shelter: 0,
  night: false,
  player: { x: 120, y: 240 },
  enemies: [
    { id: 'zombie1', x: 480, y: 140, hp: 40 },
    { id: 'zombie2', x: 620, y: 330, hp: 46 },
    { id: 'zombie3', x: 300, y: 420, hp: 52 },
  ],
  resourceNodes: {
    tree: { x: 180, y: 430, type: 'wood', amount: 3 },
    rock: { x: 580, y: 460, type: 'stone', amount: 2 },
    water: { x: 415, y: 560, type: 'water', amount: 3 },
  },
  campfire: { x: 510, y: 200 },
  shelter: { x: 200, y: 170 },
  log: [],
};

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

function addLog(message) {
  const entry = document.createElement('div');
  entry.textContent = message;
  state.log.unshift(entry.textContent);
  eventLogEl.innerHTML = '';
  state.log.slice(0, 8).forEach((item) => {
    const node = document.createElement('div');
    node.textContent = item;
    eventLogEl.appendChild(node);
  });
}

function updateInventory() {
  const items = [
    ['Wood', state.wood],
    ['Stone', state.stone],
    ['Medkits', state.meds],
    ['Shelter', state.shelter ? 'Built' : 'None'],
  ];

  inventoryEl.innerHTML = '';
  items.forEach(([label, value]) => {
    const slot = document.createElement('div');
    slot.className = 'slot ' + (value !== 0 && value !== 'None' ? 'filled' : '');
    slot.textContent = `${label}: ${value}`;
    inventoryEl.appendChild(slot);
  });
}

function setMessage(text) {
  messageBox.textContent = text;
}

function updateHud() {
  dayValue.textContent = String(state.day);
  foodValue.textContent = String(state.food);
  waterValue.textContent = String(state.water);
  healthValue.textContent = String(state.health);
  energyValue.textContent = String(state.energy);
  updateInventory();
}

function updateObjectiveList() {
  const tasks = [
    'Gather food and water',
    state.shelter > 0 ? 'Shelter is secure' : 'Build shelter',
    state.night ? 'Weather the night' : 'Survive the night',
  ];
  objectiveList.innerHTML = tasks.map((task) => `<li>${task}</li>`).join('');
}

function syncPlayer() {
  playerEl.style.left = `${state.player.x}px`;
  playerEl.style.top = `${state.player.y}px`;
}

function syncResources() {
  const resourceMap = {
    tree: document.getElementById('tree'),
    rock: document.getElementById('rock'),
    water: document.getElementById('water'),
  };

  Object.entries(state.resourceNodes).forEach(([key, node]) => {
    const el = resourceMap[key];
    if (!el) return;
    el.style.left = `${node.x}px`;
    el.style.top = `${node.y}px`;
    const visible = node.amount > 0;
    el.style.opacity = visible ? '1' : '0.15';
    el.style.filter = visible ? 'none' : 'grayscale(1)';
  });

  const campfire = document.getElementById('campfire');
  campfire.style.left = `${state.campfire.x}px`;
  campfire.style.top = `${state.campfire.y}px`;

  const shelter = document.getElementById('shelter');
  shelter.style.left = `${state.shelter.x || state.shelter}`;
  shelter.style.top = `${state.shelter.y || state.shelter}`;
}

function syncEnemies() {
  state.enemies.forEach((enemy) => {
    const el = document.getElementById(enemy.id);
    if (!el) return;
    el.style.left = `${enemy.x}px`;
    el.style.top = `${enemy.y}px`;
  });
}

function movePlayer(dx, dy) {
  const nextX = clamp(state.player.x + dx, 30, arena.clientWidth - 30);
  const nextY = clamp(state.player.y + dy, 30, arena.clientHeight - 30);
  state.player.x = nextX;
  state.player.y = nextY;
  syncPlayer();
  state.energy = clamp(state.energy - 1, 0, 100);
  if (state.night) {
    state.health = clamp(state.health - 1, 0, 100);
  }
  updateHud();
}

function findNearestResource() {
  const resources = Object.values(state.resourceNodes);
  let nearest = null;
  let minDistance = Infinity;

  resources.forEach((resource) => {
    if (resource.amount <= 0) return;
    const dist = Math.hypot(resource.x - state.player.x, resource.y - state.player.y);
    if (dist < minDistance) {
      minDistance = dist;
      nearest = resource;
    }
  });

  return nearest;
}

function collectResource() {
  const resource = findNearestResource();
  if (!resource) {
    addLog('Nothing nearby to gather.');
    setMessage('No nearby materials to collect.');
    return;
  }

  if (Math.hypot(resource.x - state.player.x, resource.y - state.player.y) > 80) {
    addLog('Move closer to the source first.');
    setMessage('You need to get closer to the resource node.');
    return;
  }

  if (resource.type === 'wood') {
    state.wood += 1;
    resource.amount -= 1;
    addLog('You chopped wood and added it to your stash.');
    setMessage('Wood gathered.');
  } else if (resource.type === 'stone') {
    state.stone += 1;
    resource.amount -= 1;
    addLog('You gathered stone for building.');
    setMessage('Stone gathered.');
  } else if (resource.type === 'water') {
    state.water = clamp(state.water + 4, 0, 100);
    resource.amount -= 1;
    addLog('You collected clean water from the stream.');
    setMessage('Water replenished.');
  }

  if (resource.amount <= 0) {
    resource.amount = 0;
  }

  state.food = clamp(state.food + 1, 0, 100);
  updateHud();
  syncResources();
}

function handleNight() {
  state.night = true;
  addLog('Night falls. The area is more dangerous now.');
  setMessage('Nightfall! Zombies are more active.');
  updateObjectiveList();
}

function rest() {
  state.energy = clamp(state.energy + 18, 0, 100);
  state.health = clamp(state.health + 8, 0, 100);
  if (state.night) {
    state.food = clamp(state.food - 2, 0, 100);
    state.water = clamp(state.water - 2, 0, 100);
  }
  addLog('You rest by the campfire and recover some strength.');
  setMessage('Rested at camp.');
  updateHud();
}

function buildShelter() {
  if (state.wood < 4 || state.stone < 2) {
    addLog('You need 4 wood and 2 stone to build a shelter.');
    setMessage('Insufficient materials for shelter.');
    return;
  }

  state.wood -= 4;
  state.stone -= 2;
  state.shelter = 1;
  addLog('A sturdy shelter rises from the wasteland.');
  setMessage('Shelter complete.');
  updateObjectiveList();
  updateHud();
}

function upgradeCamp() {
  if (state.wood < 2 || state.stone < 2) {
    addLog('Need 2 wood and 2 stone to upgrade camp.');
    setMessage('Camp upgrade needs more materials.');
    return;
  }

  state.wood -= 2;
  state.stone -= 2;
  if (state.meds < 1) {
    state.meds += 1;
  }
  state.health = clamp(state.health + 12, 0, 100);
  addLog('The camp is fortified and your supplies improve.');
  setMessage('Camp upgraded.');
  updateHud();
}

function handleEnemyAttack() {
  let totalDamage = 0;
  state.enemies.forEach((enemy) => {
    if (Math.hypot(enemy.x - state.player.x, enemy.y - state.player.y) < 80) {
      totalDamage += 7;
    }
  });

  if (totalDamage > 0) {
    state.health = clamp(state.health - totalDamage, 0, 100);
    addLog('An infected survivor lunges at you.');
    setMessage('You were attacked!');
    updateHud();
  }
}

function applyDayCycle() {
  state.day += 1;
  state.food = clamp(state.food - 4, 0, 100);
  state.water = clamp(state.water - 5, 0, 100);
  state.energy = clamp(state.energy - 8, 0, 100);

  if (state.shelter > 0) {
    state.health = clamp(state.health + 6, 0, 100);
  }

  addLog(`Day ${state.day} begins. You must survive another night.`);
  setMessage(`Day ${state.day}: Scavenge and prepare.`);
  state.night = false;
  updateObjectiveList();
  updateHud();
}

function checkWinLose() {
  if (state.health <= 0) {
    setMessage('You collapsed in the wasteland. Press the action buttons to keep trying.');
    addLog('Your survival run ended in defeat.');
    state.health = 100;
    state.food = 30;
    state.water = 28;
    state.energy = 100;
    state.day = 1;
    state.shelter = 0;
    updateHud();
    return;
  }

  if (state.day >= 5 && state.shelter > 0 && state.food > 0 && state.water > 0) {
    setMessage('You held the line. The camp survives into the next week!');
    addLog('Victory! Your camp survived the apocalypse.');
  }
}

function gameTick() {
  if (state.night) {
    handleEnemyAttack();
  }

  if (state.food <= 0 || state.water <= 0) {
    state.health = clamp(state.health - 6, 0, 100);
    addLog('You are starving and dehydrated.');
  }

  if (state.energy <= 0) {
    state.health = clamp(state.health - 5, 0, 100);
  }

  if (Math.random() < 0.4) {
    const enemy = state.enemies[Math.floor(Math.random() * state.enemies.length)];
    enemy.x = clamp(enemy.x + (Math.random() < 0.5 ? -12 : 12), 70, arena.clientWidth - 70);
    enemy.y = clamp(enemy.y + (Math.random() < 0.5 ? -12 : 12), 70, arena.clientHeight - 70);
    syncEnemies();
  }

  checkWinLose();
  updateHud();
}

function keyHandler(event) {
  const keyMap = {
    ArrowUp: [0, -18],
    ArrowDown: [0, 18],
    ArrowLeft: [-18, 0],
    ArrowRight: [18, 0],
    w: [0, -18],
    s: [0, 18],
    a: [-18, 0],
    d: [18, 0],
  };

  if (keyMap[event.key]) {
    movePlayer(...keyMap[event.key]);
  }
}

function bindActions() {
  document.querySelectorAll('[data-action]').forEach((button) => {
    button.addEventListener('click', () => {
      const action = button.dataset.action;
      if (action === 'move') {
        movePlayer(18, 0);
      }
      if (action === 'collect') {
        collectResource();
      }
      if (action === 'rest') {
        rest();
      }
      if (action === 'build') {
        buildShelter();
      }
      if (action === 'upgrade') {
        upgradeCamp();
      }
      if (action === 'night') {
        handleNight();
      }
      syncPlayer();
      syncEnemies();
      syncResources();
      updateHud();
      updateObjectiveList();
    });
  });
}

function initialize() {
  syncPlayer();
  syncResources();
  syncEnemies();
  updateHud();
  updateObjectiveList();
  bindActions();
  document.addEventListener('keydown', keyHandler);
  setMessage('Scavenge, survive, and defend the last camp.');
  addLog('Wasteland scouts report signs of life nearby.');

  setInterval(() => {
    gameTick();
    syncPlayer();
    syncEnemies();
    syncResources();
    updateObjectiveList();
  }, 4500);
}

initialize();

