179:     return;
180:   }
181: 
182:   if (resource.type === 'wood') {
183:     state.wood += 1;
184:     resource.amount -= 1;
185:     addLog('You chopped wood and added it to your stash.');
186:     setMessage('Wood gathered.');
187:   } else if (resource.type === 'stone') {
188:     state.stone += 1;
189:     resource.amount -= 1;
190:     addLog('You gathered stone for building.');
191:     setMessage('Stone gathered.');
192:   } else if (resource.type === 'water') {
193:     state.water = clamp(state.water + 4, 0, 100);
194:     resource.amount -= 1;
195:     addLog('You collected clean water from the stream.');
196:     setMessage('Water replenished.');
197:   }
198: 
199:   if (resource.amount <= 0) {
200:     resource.amount = 0;
201:   }
202: 
203:   state.food = clamp(state.food + 1, 0, 100);
204:   updateHud();
205:   syncResources();
206: }
207: 
208: function handleNight() {
209:   state.night = true;
210:   addLog('Night falls. The area is more dangerous now.');
211:   setMessage('Nightfall! Zombies are more active.');
212:   updateObjectiveList();
213: }
214: 
215: function rest() {
216:   state.energy = clamp(state.energy + 18, 0, 100);
217:   state.health = clamp(state.health + 8, 0, 100);
218:   if (state.night) {
219:     state.food = clamp(state.food - 2, 0, 100);
220:     state.water = clamp(state.water - 2, 0, 100);
221:   }
222:   addLog('You rest by the campfire and recover some strength.');
223:   setMessage('Rested at camp.');
224:   updateHud();
225: }
226: 
227: function buildShelter() {
228:   if (state.wood < 4 || state.stone < 2) {
229:     addLog('You need 4 wood and 2 stone to build a shelter.');
230:     setMessage('Insufficient materials for shelter.');
231:     return;
232:   }
233: 
234:   state.wood -= 4;
235:   state.stone -= 2;
236:   state.shelter = 1;
237:   state.shelterPosition = { x: 200, y: 170 };
238:   addLog('A sturdy shelter rises from the wasteland.');
239:   setMessage('Shelter complete.');
240:   updateObjectiveList();
241:   updateHud();
242: }
243: 
244: function upgradeCamp() {
245:   if (state.wood < 2 || state.stone < 2) {
246:     addLog('Need 2 wood and 2 stone to upgrade camp.');
247:     setMessage('Camp upgrade needs more materials.');
248:     return;
249:   }
250: 
251:   state.wood -= 2;
252:   state.stone -= 2;
253:   if (state.meds < 1) {
254:     state.meds += 1;
255:   }
256:   state.health = clamp(state.health + 12, 0, 100);
257:   addLog('The camp is fortified and your supplies improve.');
258:   setMessage('Camp upgraded.');
259:   updateHud();
260: }
261: 
262: function handleEnemyAttack() {
263:   let totalDamage = 0;
264:   state.enemies.forEach((enemy) => {
265:     if (Math.hypot(enemy.x - state.player.x, enemy.y - state.player.y) < 80) {
266:       totalDamage += 7;
267:     }
268:   });
269: 
270:   if (totalDamage > 0) {
271:     state.health = clamp(state.health - totalDamage, 0, 100);
272:     addLog('An infected survivor lunges at you.');
273:     setMessage('You were attacked!');
274:     updateHud();
275:   }
276: }
277: 
278: function applyDayCycle() {
279:   state.day += 1;
280:   state.food = clamp(state.food - 4, 0, 100);
281:   state.water = clamp(state.water - 5, 0, 100);
282:   state.energy = clamp(state.energy - 8, 0, 100);
283: 
284:   if (state.shelter > 0) {
285:     state.health = clamp(state.health + 6, 0, 100);
286:   }
287: 
288:   addLog(`Day ${state.day} begins. You must survive another night.`);
289:   setMessage(`Day ${state.day}: Scavenge and prepare.`);
290:   state.night = false;
291:   updateObjectiveList();
292:   updateHud();
293: }
294: 
295: function checkWinLose() {
296:   if (state.health <= 0) {
297:     setMessage('You collapsed in the wasteland. Press the action buttons to keep trying.');
298:     addLog('Your survival run ended in defeat.');
299:     state.health = 100;
300:     state.food = 30;
301:     state.water = 28;
302:     state.energy = 100;
303:     state.day = 1;
304:     state.shelter = 0;
305:     state.shelterPosition = { x: 220, y: 170 };
306:     updateHud();
307:     return;
308:   }
309: 
310:   if (state.day >= 5 && state.shelter > 0 && state.food > 0 && state.water > 0) {
311:     setMessage('You held the line. The camp survives into the next week!');
312:     addLog('Victory! Your camp survived the apocalypse.');
313:   }
314: }
315: 
316: function gameTick() {
317:   if (state.night) {
318:     handleEnemyAttack();
319:   }
320: 
321:   if (state.food <= 0 || state.water <= 0) {
322:     state.health = clamp(state.health - 6, 0, 100);
323:     addLog('You are starving and dehydrated.');
324:   }
325: 
326:   if (state.energy <= 0) {
327:     state.health = clamp(state.health - 5, 0, 100);
328:   }
329: 
330:   if (Math.random() < 0.4) {
331:     const enemy = state.enemies[Math.floor(Math.random() * state.enemies.length)];
332:     enemy.x = clamp(enemy.x + (Math.random() < 0.5 ? -12 : 12), 70, arena.clientWidth - 70);
333:     enemy.y = clamp(enemy.y + (Math.random() < 0.5 ? -12 : 12), 70, arena.clientHeight - 70);
334:     syncEnemies();
335:   }
336: 
337:   checkWinLose();
338:   updateHud();
339: }
340: 
341: function keyHandler(event) {
342:   const keyMap = {
343:     ArrowUp: [0, -18],
344:     ArrowDown: [0, 18],
345:     ArrowLeft: [-18, 0],
346:     ArrowRight: [18, 0],
347:     w: [0, -18],
348:     s: [0, 18],
349:     a: [-18, 0],
350:     d: [18, 0],
351:   };
352: 
353:   if (keyMap[event.key]) {
354:     movePlayer(...keyMap[event.key]);
355:   }
356: }
357: 
358: function bindActions() {
359:   document.querySelectorAll('[data-action]').forEach((button) => {
360:     button.addEventListener('click', () => {
361:       const action = button.dataset.action;
362:       if (action === 'move') {
363:         movePlayer(18, 0);
364:       }
365:       if (action === 'collect') {
366:         collectResource();
367:       }
368:       if (action === 'rest') {
369:         rest();
370:       }
371:       if (action === 'build') {
372:         buildShelter();
373:       }
374:       if (action === 'upgrade') {
375:         upgradeCamp();
376:       }
377:       if (action === 'night') {
378:         handleNight();
379:       }
380:       syncPlayer();
381:       syncEnemies();
382:       syncResources();
383:       updateHud();
384:       updateObjectiveList();
385:     });
386:   });
387: }
388: 
389: function initialize() {
390:   syncPlayer();
391:   syncResources();
392:   syncEnemies();
393:   updateHud();
394:   updateObjectiveList();
395:   bindActions();
396:   document.addEventListener('keydown', keyHandler);
397:   setMessage('Scavenge, survive, and defend the last camp.');
398:   addLog('Wasteland scouts report signs of life nearby.');
399: 
400:   setInterval(() => {
401:     gameTick();
402:     syncPlayer();
403:     syncEnemies();
404:     syncResources();
405:     updateObjectiveList();
406:   }, 4500);
407: }
408: 
409: setInterval(() => {
410:   if (!state.night) {
411:     const random = Math.random();
412:     if (random > 0.8) {
413:       handleNight();
414:     }
415:   }
416: }, 12000);
417: 
418: initialize();

